import org.joda.convert.FromString;
import org.joda.convert.ToString;
import org.joda.time.base.BaseLocal;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.convert.ConverterManager;
import org.joda.time.convert.PartialConverter;
import org.joda.time.field.AbstractReadableInstantFieldProperty;
import org.joda.time.format.DateTimeFormat;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;

public class LocalDateTimeTest{
@Test
    public void testFromDateFields_Null() {
        try {
            LocalDateTime.fromDateFields(null);
            Assert.fail();
        } catch (IllegalArgumentException e) {
            Assert.assertEquals("The date must not be null", e.getMessage());
        }
    }

    @Test
    public void testFromDateFields_BC() {
        GregorianCalendar cal = new GregorianCalendar(1, 0, 1, 0, 0, 0);
        cal.setTimeZone(TimeZone.getDefault());
        LocalDateTime dateTime = LocalDateTime.fromDateFields(cal.getTime());
        Assert.assertEquals(1, dateTime.getYear());
        Assert.assertEquals(1, dateTime.getMonthOfYear());
        Assert.assertEquals(1, dateTime.getDayOfMonth());
        Assert.assertEquals(0, dateTime.getHourOfDay());
        Assert.assertEquals(0, dateTime.getMinuteOfHour());
        Assert.assertEquals(0, dateTime.getSecondOfMinute());
        Assert.assertEquals(0, dateTime.getMillisOfSecond());
    }

    @Test
    public void testFromDateFields_AD() {
        Date date = new Date(System.currentTimeMillis());
        LocalDateTime dateTime = LocalDateTime.fromDateFields(date);
        Assert.assertEquals(date.getYear() + 1900, dateTime.getYear());
        Assert.assertEquals(date.getMonth() + 1, dateTime.getMonthOfYear());
        Assert.assertEquals(date.getDate(), dateTime.getDayOfMonth());
        Assert.assertEquals(date.getHours(), dateTime.getHourOfDay());
        Assert.assertEquals(date.getMinutes(), dateTime.getMinuteOfHour());
        Assert.assertEquals(date.getSeconds(), dateTime.getSecondOfMinute());
        Assert.assertTrue(dateTime.getMillisOfSecond() > 0);
    }

    @Test
    public void testFromDateFields_Time() {
        Date date = new Date();
        long time = date.getTime();
        date.setTime(time - (time % 1000));
        LocalDateTime dateTime = LocalDateTime.fromDateFields(date);
        Assert.assertEquals(0, dateTime.getMillisOfSecond());
    }
}
