public class BasicMonthOfYearDateTimeFieldTest{
BasicMonthOfYearDateTimeField field;

    @Before
    public void beforeTest(){
        field = mock(BasicMonthOfYearDateTimeField.class);
    }

    @Test
    public void testAdd_NoChange() {
        ReadablePartial partial = mock(ReadablePartial.class);
        when(partial.size()).thenReturn(0);
        int fieldIndex = 0;
        int[] values = {1};
        int valueToAdd = 0;

        int[] result = field.add(partial, fieldIndex, values, valueToAdd);

        assertArrayEquals(values, result);
    }

    @Test
    public void testAdd_MonthOnly() {
        ReadablePartial partial = mock(ReadablePartial.class);
        when(partial.size()).thenReturn(1);
        when(partial.getFieldType(0)).thenReturn(DateTimeFieldType.monthOfYear());
        when(partial.getValue(0)).thenReturn(5);
        int fieldIndex = 0;
        int[] values = {5};
        int valueToAdd = 12;

        int[] result = field.add(partial, fieldIndex, values, valueToAdd);

        assertEquals(5, result[0]);
    }

