        when(partial.getValue(0)).thenReturn(12);
        int fieldIndex = 0;
        int[] values = {12};
        int valueToAdd = 1;

        int[] result = field.add(partial, fieldIndex, values, valueToAdd);

        assertEquals(1, result[0]);
    }

    @Test
    public void testAdd_Contiguous() {
        ReadablePartial partial = mock(ReadablePartial.class);
        when(partial.size()).thenReturn(2);
        when(DateTimeUtils.isContiguous(partial)).thenReturn(true);
        int fieldIndex = 0;
        int[] values = {5, 10};
        int valueToAdd = 1;

        long instant = 0L;
        for (int i = 0; i < partial.size(); i++) {
            instant = DateTimeFieldType.monthOfYear().getField(null).set(instant, values[i]);
        }
        instant = field.add(instant, valueToAdd);
        int[] expected = field.iChronology.get(partial, instant);

        int[] result = field.add(partial, fieldIndex, values, valueToAdd);

        assertArrayEquals(expected, result);
    }

    @Test
    public void testAdd_NotContiguous() {
        ReadablePartial partial = mock(ReadablePartial.class);
