    @Before
    public void setup(){
        bucket = new DateTimeParserBucket(0, null, Locale.US);
    }

    @Test
    public void testComputeMillis(){
        bucket.saveField(DateTimeFieldType.year(), 2022);
        assertEquals(1640995200000L, bucket.computeMillis(false, null));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testComputeMillis_IllegalArgumentException(){
        bucket.saveField(DateTimeFieldType.hourOfDay(), 25);
        bucket.computeMillis(false, null);
    }

    @Test
    public void testComputeMillis_ResetFields(){
        bucket.saveField(DateTimeFieldType.year(), 2022);
        bucket.saveField(DateTimeFieldType.monthOfYear(), 2);
        assertEquals(1643721600000L, bucket.computeMillis(true, null));
    }

    @Test
    public void testComputeMillis_Text(){
        bucket.saveField(DateTimeFieldType.year(), 2022);
        bucket.saveField(DateTimeFieldType.monthOfYear(), 2);
        assertEquals(1643721600000L, bucket.computeMillis(false, "2022-02"));
    }

    @Test(expected = IllegalFieldValueException.class)
    public void testComputeMillis_IllegalFieldValueException(){
        bucket.saveField(DateTimeFieldType.monthOfYear(), 13);
        bucket.computeMillis(false, "2022-13");
    }

    @Test
    public void testComputeMillis_TimeZone(){
        bucket.setZone(DateTimeZone.forOffsetHours(1));
        bucket.saveField(DateTimeFieldType.year(), 2022);
        assertEquals(1641012000000L, bucket.computeMillis(false, null));
    }

    @Test
    public void testComputeMillis_TimeZoneOffsetTransition(){
        DateTimeZone zone = DateTimeZone.forID("Europe/London");
        bucket.setZone(zone);
        bucket.saveField(DateTimeFieldType.year(), 2022);
        bucket.saveField(DateTimeFieldType.monthOfYear(), 10);
        bucket.saveField(DateTimeFieldType.dayOfMonth(), 27);
        bucket.saveField(DateTimeFieldType.hourOfDay(), 0);
        assertEquals(1635379200000L, bucket.computeMillis(false, null));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testComputeMillis_TimeZoneOffsetTransitionException(){
        DateTimeZone zone = DateTimeZone.forID("Europe/London");
        bucket.setZone(zone);
        bucket.saveField(DateTimeFieldType.year(), 2022);
        bucket.saveField(DateTimeFieldType.monthOfYear(), 10);
        bucket.saveField(DateTimeFieldType.dayOfMonth(), 28);
        bucket.saveField(DateTimeFieldType.hourOfDay(), 0);
        bucket.computeMillis(false, null);
    }

    @Test
    public void testComputeMillis_MonthOrDayFirst(){
        DurationField months = DurationFieldType.months().getField(DateTimeUtils.ISOChronology);
        Mockito.when(bucket.iChrono.getDurationField()).thenReturn(months);
        bucket.saveField(DateTimeFieldType.monthOfYear(), 2);
        assertEquals(1643721600000L, bucket.computeMillis(false, null));
    }

    @Test
    public void testComputeMillis_NoSavedFields(){
        assertEquals(0, bucket.computeMillis(false, null));
    }
}
